-- GENERATED by `wfj generate` from data/book/. Do not edit: `wfj validate` regenerates and diffs it.
local _, WFJ = ...
WFJ.Data.add("book", {
  ["c34e9175308d1246"] = { "Gli elfi, guidati a quel tempo da Anasterian Sunstrider, erano in gran parte indifferenti al conflitto imminente. Tuttavia erano tenuti per dovere ad aiutare Lothar, perché egli era l'ultimo discendente della stirpe di Arathi, che in epoche passate aveva soccorso gli elfi.", "." },
  ["c388a16eb63bf39c"] = { "Gli imperi Gurubashi e Amani non si amavano granché, ma di rado si facevano guerra. A quel tempo il loro più grande nemico comune era un terzo impero: la civiltà di Azj'Aqir. Gli aqir erano insettoidi intelligenti che dominavano le terre del lontano ovest. Questi astuti insettoidi erano fortemente espansionisti e incredibilmente malvagi. Gli aqir erano ossessionati dall'idea di sradicare dalle pianure di Kalimdor ogni forma di vita che non fosse insetto.", "." },
  ["c38c4f289103d6f3"] = { "Fu Gul'dan il responsabile del declino dello sciamanesimo tra i clan. La promessa di potere e di controllo sui propri nemici rendeva le sue offerte ancora più allettanti. Con l'aiuto di Kil'jaeden, Gul'dan cominciò a manipolare i clan. Gli orchi, un tempo nobili, divennero selvaggi corrotti e senza cervello. Con l'introduzione del sangue demoniaco nei loro corpi, gli orchi divennero ancora più spietati e barbari.", "." },
  ["c393139c7900538a"] = { "Ora che la maledizione demoniaca era finita, l'⟦Horde=Orda⟧ si trasformò da inarrestabile macchina da guerra in una coalizione più libera, dedita alla sopravvivenza e alla prosperità piuttosto che alla conquista. Aiutati dai nobili tauren e dagli astuti troll della tribù ⟦Darkspear=Lanciascura⟧, Thrall e i suoi orchi guardavano a una nuova era di pace nella loro terra.", "." },
  ["c39768280cf5ac5d"] = { "Tyrande, che era divenuta la somma sacerdotessa di Elune, chiese al suo amato Malfurion di non lasciarla per il ⟦Emerald Dream=Sogno di Smeraldo⟧ di Ysera. Ma Malfurion, vincolato dall'onore a entrare nei mutevoli Sentieri del Sogno, disse addio alla sacerdotessa e giurò che non sarebbero mai stati separati finché fossero rimasti fedeli al loro amore.", "." },
  ["c3a592e04dc94a5a"] = { "La sorte di Horgus il Devastatore\n\nHorgus il Devastatore cadde nella battaglia del ⟦Darrowshire=Borgo di Darrow⟧. Ma il male che era in lui non si era del tutto esaurito. Le forze vittoriose del Flagello portarono via il suo teschio dal campo di battaglia del ⟦Darrowshire=Borgo di Darrow⟧ e lo tennero con sé per seminare il terrore tra i vivi che affrontavano.\n\nGiorni dopo, la compagnia del Flagello che possedeva la testa fu sconfitta dai Paladini della ⟦Silver Hand=Mano d'Argento⟧. La testa di Horgus fu gettata nel ⟦Blackwood Lake=Lago di Selvanera⟧.", "." },
  ["c3cb54577f8c4203"] = { "ISALIEN\n\nSacerdotessa della Luna elfa della notte\n\nQuando decise di lasciare la compagnia, Isalien lo fece con l'intenzione di compiere un pellegrinaggio a ⟦Dire Maul=Maglio Infausto⟧, l'antica città caduta degli elfi della notte, un tempo nota come Eldre'Thalas. Lì sorge ancora una biblioteca di grande sapienza, un santuario in cui un piccolo gruppo di elfi della notte è riuscito ad arginare la marea. Era decisa a trovare risposte sulle proprie origini e, forse, anche sui frammenti dell'amuleto. Va notato che era anche una buona amica di Falrin Treeshaper.", "." },
  ["c3de158687dd34ce"] = { "Aegwynn, un'ardente ragazza umana, ottenne l'approvazione dell'Ordine e ricevette il manto di Guardiana. Aegwynn si dedicò con vigore a dare la caccia ai demoni e a sterminarli ovunque li trovasse, ma spesso metteva in discussione l'autorità del Consiglio di Tirisfal, dominato dagli uomini.", "." },
  ["c3fc3c4c8a07706f"] = { "Posso solo immaginare perché sono sopravvissuto quella notte. Sono sempre stato prudente, sempre pronto a scansare i colpi e a evitare le trappole con un balzo. Il mio soprannome, Jitters, viene da questo tratto. Così forse è stata proprio quella dote di prudenza a salvarmi...\n\nO forse è stata la Falce che ho estratto dalle macerie. Non può essere la Falce in sé, perché l'ho persa durante la mia fuga disperata. Ma se sono stato io a portare i worgen a ⟦Duskwood=Boscovespro⟧, forse i worgen mi hanno concesso una rara cortesia. Che siano maledetti.", "." },
})
